create extension if not exists pgcrypto;
create table if not exists products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text,price numeric(10,2) not null,images jsonb default '[]',category text,variants jsonb default '[]',stock_qty int default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists orders(id text primary key,customer jsonb not null,items jsonb not null,subtotal numeric(10,2) not null,shipping_fee numeric(10,2) default 0,total numeric(10,2) not null,payment_status text default 'pending',order_status text default 'new',tracking_id text,courier text,razorpay_order_id text,razorpay_payment_id text,created_at timestamptz default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id text references orders(id) on delete cascade,razorpay_order_id text,razorpay_payment_id text,signature text,status text,created_at timestamptz default now());
create table if not exists store_settings(id int primary key default 1,store_name text default 'KASHORIA',tagline text default 'Handmade with Love',upi_id text,shipping_fee numeric(10,2) default 0,updated_at timestamptz default now());
